import{_ as r,a0 as l,w as p,s as d,I as t,x as n,a1 as i,A as a,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何在RedHat/CentOS 7.x中使用nmcli管理網絡 | LCTT x X-CMD","titleTemplate":false,"description":"如何在RedHat/CentOS 7.x中使用nmcli管理網絡 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在RedHat/CentOS 7.x中使用nmcli管理網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在RedHat/CentOS 7.x中使用nmcli管理網絡 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x","title":"如何在RedHat/CentOS 7.x中使用nmcli管理網絡","tag":"201502","desc":""},"relativePath":"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x.md","filePath":"[post].md"}'),s={name:"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x.md"};function c(C,e,g,u,T,x){const o=l("Link");return p(),d("div",null,[e[19]||(e[19]=t("h1",{id:"如何在redhat-centos-7-x中使用nmcli管理網絡",tabindex:"-1"},[n("如何在RedHat/CentOS 7.x中使用nmcli管理網絡 "),t("a",{class:"header-anchor",href:"#如何在redhat-centos-7-x中使用nmcli管理網絡","aria-label":"Permalink to “如何在RedHat/CentOS 7.x中使用nmcli管理網絡”"},"​")],-1)),t("p",null,[i(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/7.0_Release_Notes/"},{default:a(()=>[...e[0]||(e[0]=[t("strong",null,"Red Hat Enterprise Linux 7",-1)])]),_:1}),e[1]||(e[1]=n("和",-1)),e[2]||(e[2]=t("strong",null,"CentOS 7",-1)),e[3]||(e[3]=n("的一個新特性是默認的網絡服務由",-1)),e[4]||(e[4]=t("strong",null,"NetworkManager",-1)),e[5]||(e[5]=n("提供，這是一個動態的網絡控制和配置守護進程，它在網絡設備和連接可用時保持鏈接正常，同時也提供了典型的ifcfg類型的配置文件。NetworkManager可以用於下面這些連接：Ethernet、 VLANs、橋接、Bonds、Teams、 Wi-Fi、 移動寬帶 (比如 3G)和IP-over-InfiniBand(IPoIB)。",-1))]),e[20]||(e[20]=m(`<p>NetworkManager可以由命令列工具<strong>nmcli</strong>控制。</p><h3 id="nmcli的通常用法" tabindex="-1">nmcli的通常用法 <a class="header-anchor" href="#nmcli的通常用法" aria-label="Permalink to “nmcli的通常用法”">​</a></h3><p>nmcli的通常語法是：</p><pre><code># nmcli [ OPTIONS ] OBJECT { COMMAND | help }
</code></pre><p>一件很酷的事情是你可以使用tab鍵來補全操作，這樣你在何時忘記了語法你都可以按下tab來看到可用的選項了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-tab.jpg" alt="nmcli tab"></p><p>nmcli通常用法的一些例子：</p><pre><code># nmcli general status
</code></pre><p>會顯示NetworkManager的整體狀態。</p><pre><code># nmcli connection show
</code></pre><p>會顯示所有的連接</p><pre><code># nmcli connection show -a
</code></pre><p>僅顯示活躍的連接</p><pre><code># nmcli device status
</code></pre><p>顯示NetworkManager識別的設備列表和它們當前的狀態。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-gneral.jpg" alt="nmcli general"></p><h3 id="啓動-停止網絡設備" tabindex="-1">啓動/停止網絡設備 <a class="header-anchor" href="#啓動-停止網絡設備" aria-label="Permalink to “啓動/停止網絡設備”">​</a></h3><p>你可以使用nmcli從命令列啓動或者停止網絡設備，這等同於ifconfig中的up和down。</p><p>停止網絡設備使用下面的語法：</p><pre><code># nmcli device disconnect eno16777736
</code></pre><p>要啓動它使用下面的語法：</p><pre><code># nmcli device connect eno16777736
</code></pre><h3 id="添加一個使用靜態ip的以太網連接" tabindex="-1">添加一個使用靜態IP的以太網連接 <a class="header-anchor" href="#添加一個使用靜態ip的以太網連接" aria-label="Permalink to “添加一個使用靜態IP的以太網連接”">​</a></h3><p>要用靜態IP添加一個以太網連接可以使用下面的命令：</p><pre><code># nmcli connection add type ethernet con-name NAME_OF_CONNECTION ifname INTERFACE-NAME ip4 IP_ADDRESS gw4 GW_ADDRESS
</code></pre><p>將NAME_OF_CONNECTION替換成新的連接名（LCTT 譯註：這個名字以後可以用來對其操作，可以使用任何簡單明瞭的名稱），INTERFACE-NAME 替換成你的接口名，IP_ADDRESS替換成你要的IP地址，GW_ADDRESS替換成你使用的網關地址（如果你並不使用網關，你可以忽略這部分）。</p><pre><code># nmcli connection add type ethernet con-name NEW_STATIC ifname eno16777736 ip4 192.168.1.141 gw4 192.168.1.1
</code></pre><p>要設置這個連接所使用的DNS服務器使用下面的命令：</p><pre><code># nmcli connection modify NEW_STATIC ipv4.dns &quot;8.8.8.8 8.8.4.4&quot;
</code></pre><p>要啓用新的以太網連接，使用下面的命令：</p><pre><code># nmcli connection up NEW_STATIC ifname eno16777736
</code></pre><p>要查看新配置連接的詳細信息，使用下面的命令：</p><pre><code># nmcli -p connection show NEW_STATIC
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-add-static.jpg" alt="nmcli add static"></p><h3 id="添加一個使用dhcp的連接" tabindex="-1">添加一個使用DHCP的連接 <a class="header-anchor" href="#添加一個使用dhcp的連接" aria-label="Permalink to “添加一個使用DHCP的連接”">​</a></h3><p>如果你想要添加一個使用DHCP來配置接口IP地址、網關地址和dns服務器地址的新的連接，你要做的就是忽略上述命令中的ip/gw部分，NetworkManager會自動使用DHCP來獲取配置細節。</p><p>比如，要創建一個新的叫NEW_DHCP的DHCP連接，在設備eno16777736上你可以使用下面的命令：</p><pre><code># nmcli connection add type ethernet con-name NEW_DHCP ifname eno16777736
</code></pre><hr>`,39)),t("p",null,[e[7]||(e[7]=n("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/"},{default:a(()=>[...e[6]||(e[6]=[n("http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=n("作者：",-1)),i(o,{href:"http://linoxide.com/author/adriand/"},{default:a(()=>[...e[8]||(e[8]=[n("Adrian Dinu",-1)])]),_:1}),e[12]||(e[12]=n(" 譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:a(()=>[...e[9]||(e[9]=[n("geekpi",-1)])]),_:1}),e[13]||(e[13]=n(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=n("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[n("LCTT",-1)])]),_:1}),e[17]||(e[17]=n(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[n("Linux中國",-1)])]),_:1}),e[18]||(e[18]=n(" 榮譽推出",-1))])])}const w=r(s,[["render",c]]);export{S as __pageData,w as default};
